effect.shader:
vec4 preMultiplicada(vec4 c) { return vec4(c.rgb * c.a, c.a); }

// O filtro linear da GPU, à mão, sobre o fundo PRÉ-multiplicado (a textura do AM é assim): os 4 pixels em
// volta, presos à borda como o CLAMP_TO_EDGE.
vec4 fundoNoPonto(vec2 uv) {
    ivec2 T = textureSize(comp, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    ivec2 m = T - 1;
    vec4 c00 = preMultiplicada(texelFetch(comp, clamp(a, ivec2(0), m), 0));
    vec4 c10 = preMultiplicada(texelFetch(comp, clamp(a + ivec2(1, 0), ivec2(0), m), 0));
    vec4 c01 = preMultiplicada(texelFetch(comp, clamp(a + ivec2(0, 1), ivec2(0), m), 0));
    vec4 c11 = preMultiplicada(texelFetch(comp, clamp(a + ivec2(1, 1), ivec2(0), m), 0));
    return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

// A volta do `acTela`: UV da tela → UV do buffer da camada (a homografia inversa).
vec2 daTela(vec2 t) {
    vec3 c = inverse(acParaTela) * vec3(t, 1.0);
    return c.xy / c.z;
}

// O alfa da camada num pixel da TELA, como o compositor o pinta: o buffer lido no meio do pixel; fora do
// buffer, nada. O pixel fora da tela vira o da borda (o CLAMP_TO_EDGE da textura do AM).
float alfaDoPixel(ivec2 px, ivec2 T) {
    px = clamp(px, ivec2(0), T - 1);
    vec2 uv = daTela((vec2(px) + 0.5) / vec2(T));
    if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return 0.0;
    return texture(inputImg, uv).a;
}

// A camada já na tela, filtrada de novo no ponto ampliado: a leitura do `inputImg` do AM com Camada ampliada.
float alfaNoPonto(vec2 uv) {
    ivec2 T = textureSize(comp, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    return mix(
        mix(alfaDoPixel(a, T), alfaDoPixel(a + ivec2(1, 0), T), f.x),
        mix(alfaDoPixel(a + ivec2(0, 1), T), alfaDoPixel(a + ivec2(1, 1), T), f.x),
        f.y
    );
}

void main() {
    // Tudo no espaço da tela do `acTela` (o mesmo do fundo): o centro e o ponto andam juntos, em qualquer
    // orientação. O meio do conteúdo é o meio do buffer da camada, levado à tela pela `acCamadaParaTela` — que
    // vale também quando a cadeia já roda na tela (`stage="screen"`: aí o `acTela` é a identidade).
    vec2 tela = acTela(acScreenNorm);
    vec2 centro = acCamadaNaTela(vec2(0.5));

    // O ponto da camada aproximado do meio dela ÷ Escala, de volta na tela (a conta do AM, sem a ida e volta
    // pela coordenada da camada, que é afim).
    vec2 ponto = centro + (tela - centro) / scale;
    if (sampling == 0) {
        // Mais próximo: o meio do pixel da composição.
        ponto *= acTamanhoDaTela;
        ponto = floor(ponto) + 0.5;
        ponto /= acTamanhoDaTela;
    }

    vec4 fundo = fundoNoPonto(ponto);
    float alfa = scaleMask ? alfaNoPonto(ponto) : texture(inputImg, acScreenNorm).a;

    vec4 saida = fundo * alfa;   // pré-multiplicada, como o AM
    fragColor = saida.a > 0.0 ? vec4(saida.rgb / saida.a, saida.a) : vec4(0.0);
}
